import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

/**
 * Generates tokens.css and tailwind-theme.css from tokens.json (Nexus Style).
 * `--check` fails when the generated files are stale (run by `lint`).
 */

interface ColorToken {
  name: string;
  value: {
    light: string;
    dark: string;
  };
  usage: string;
}

interface TypeStyle {
  name: string;
  fontSize: string;
  lineHeight?: number | string;
  fontWeight?: number | string;
  letterSpacing?: string;
  usage?: string;
}

interface TypeGroup {
  name: string;
  family: string;
  styles: TypeStyle[];
}

interface NamedValue {
  name: string;
  value: string;
  usage: string;
}

interface DensityPreset {
  name: string;
  scale: number;
  usage: string;
}

interface TokensData {
  name: string;
  version: number;
  color: {
    themes: { id: string; name: string }[];
    tokens: ColorToken[];
  };
  type: {
    families: {
      sans: string;
      mono: string;
    };
    groups: TypeGroup[];
  };
  spacing: { tokens: NamedValue[] };
  density: { default: string; presets: DensityPreset[] };
  radius: { tokens: NamedValue[] };
  size: { tokens: NamedValue[] };
}

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const packageDir = path.resolve(__dirname, "..");

const tokensJsonPath = path.join(packageDir, "src", "theme", "tokens.json");
const tokensCssPath = path.join(packageDir, "src", "theme", "tokens.css");
const tailwindThemeCssPath = path.join(packageDir, "src", "theme", "tailwind-theme.css");

function defaultDensityScale(tokens: TokensData): number {
  const preset = tokens.density.presets.find((p) => p.name === tokens.density.default);
  if (!preset) throw new Error(`Unknown default density: ${tokens.density.default}`);
  return preset.scale;
}

export function generateTokensCss(tokens: TokensData): string {
  const lines: string[] = [
    "/* Generated by scripts/build-tokens.ts. Do not edit directly. */",
    "",
    ":root {",
    `  --font-sans: ${tokens.type.families.sans};`,
    `  --font-mono: ${tokens.type.families.mono};`,
  ];

  for (const token of tokens.spacing.tokens) {
    lines.push(`  --${token.name}: ${token.value};`);
  }
  lines.push(`  --density-scale: ${defaultDensityScale(tokens)};`);
  for (const token of tokens.radius.tokens) {
    lines.push(`  --${token.name}: ${token.value};`);
  }
  for (const token of tokens.size.tokens) {
    lines.push(`  --${token.name}: ${token.value};`);
  }
  lines.push("}");
  lines.push("");

  // Light is the default theme (D7): it applies with no data-theme attribute.
  lines.push(":root,");
  lines.push('[data-theme="light"] {');
  for (const token of tokens.color.tokens) {
    lines.push(`  --${token.name}: ${token.value.light};`);
  }
  lines.push("}");
  lines.push("");

  lines.push('[data-theme="dark"] {');
  for (const token of tokens.color.tokens) {
    lines.push(`  --${token.name}: ${token.value.dark};`);
  }
  lines.push("}");
  lines.push("");

  for (const preset of tokens.density.presets) {
    lines.push(`[data-density="${preset.name}"] {`);
    lines.push(`  --density-scale: ${preset.scale};`);
    lines.push("}");
    lines.push("");
  }

  return lines.join("\n");
}

export function generateTailwindThemeCss(tokens: TokensData): string {
  const lines: string[] = [
    "/* Generated by scripts/build-tokens.ts. Do not edit directly. */",
    "",
    "@theme inline {",
    "  --color-*: initial;",
    "  --radius-*: initial;",
    "  --text-*: initial;",
    "  --font-*: initial;",
    "",
  ];

  for (const token of tokens.color.tokens) {
    lines.push(`  --color-${token.name}: var(--${token.name});`);
  }

  lines.push("");
  lines.push("  --font-sans: var(--font-sans);");
  lines.push("  --font-mono: var(--font-mono);");
  lines.push("");

  for (const group of tokens.type.groups) {
    for (const style of group.styles) {
      lines.push(`  --text-${style.name}: ${style.fontSize};`);
      if (style.lineHeight !== undefined) {
        lines.push(`  --text-${style.name}--line-height: ${style.lineHeight};`);
      }
      if (style.fontWeight !== undefined) {
        lines.push(`  --text-${style.name}--font-weight: ${style.fontWeight};`);
      }
      if (style.letterSpacing !== undefined) {
        lines.push(`  --text-${style.name}--letter-spacing: ${style.letterSpacing};`);
      }
    }
  }

  lines.push("");
  // Density (C-1) scales every spacing utility (p-4, gap-2, …) through one variable.
  lines.push("  --spacing: calc(var(--space-1) * var(--density-scale));");
  lines.push("");

  for (const token of tokens.radius.tokens) {
    lines.push(`  --${token.name}: var(--${token.name});`);
  }

  lines.push("}");
  lines.push("");

  return lines.join("\n");
}

function main(): void {
  const isCheck = process.argv.includes("--check");
  const tokens = JSON.parse(fs.readFileSync(tokensJsonPath, "utf-8")) as TokensData;

  const expectedTokensCss = generateTokensCss(tokens);
  const expectedTailwindCss = generateTailwindThemeCss(tokens);

  if (isCheck) {
    const stale = [
      [tokensCssPath, expectedTokensCss],
      [tailwindThemeCssPath, expectedTailwindCss],
    ].some(
      ([file, expected]) =>
        !fs.existsSync(file!) ||
        fs.readFileSync(file!, "utf-8").replace(/\r\n/g, "\n") !== expected,
    );
    if (stale) {
      console.error(
        "Theme tokens CSS is stale. Run 'pnpm --filter @nexus/ui-core tokens' to regenerate.",
      );
      process.exit(1);
    }
    console.log("Theme tokens CSS is up to date.");
    process.exit(0);
  }

  fs.writeFileSync(tokensCssPath, expectedTokensCss, "utf-8");
  fs.writeFileSync(tailwindThemeCssPath, expectedTailwindCss, "utf-8");
  console.log("Theme tokens CSS generated successfully.");
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  main();
}
